#!/usr/bin/env python3
"""Run actual original IGV installer/packaged dependency and integrity controls.

Creates disposable private control homes under --out. It never edits the selected
JDK or normal runtime. Corrupt control software is retained and never executed.
"""
from __future__ import annotations
import argparse,datetime as dt,hashlib,importlib.util,json,shutil,subprocess,sys
from pathlib import Path
sys.dont_write_bytecode=True
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--java',required=True);parser.add_argument('--jar',required=True,type=Path);parser.add_argument('--home',required=True,type=Path);parser.add_argument('--cache',required=True,type=Path);parser.add_argument('--out',required=True,type=Path);parser.add_argument('--allow-download-test',action='store_true');args=parser.parse_args(argv);out=args.out.absolute();out.mkdir(parents=True,exist_ok=False);runs=[];normal_marker=sha(args.home/'.jlinalg-igv.json');record=dict(status='running',started_utc=dt.datetime.now(dt.timezone.utc).isoformat(),jar_sha256=sha(args.jar),normal_runtime_marker_sha256=normal_marker,runs=runs)
    spec=importlib.util.spec_from_file_location('igv_example',ROOT/'examples/igv-tools/run-workflow.py');example=importlib.util.module_from_spec(spec);spec.loader.exec_module(example);views=out/'views.json';views.write_text(json.dumps(example.recipe()),encoding='utf-8')
    def install(name,home,cache,expected,flags=()):
        report=out/(name+'-report');command=[sys.executable,'-X','utf8',str(ROOT/'tools/literature/install_igv.py'),'--java',args.java,'--home',str(home),'--cache',str(cache),'--report-dir',str(report),*flags];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=300);(out/(name+'.stdout')).write_bytes(r.stdout);(out/(name+'.stderr')).write_bytes(r.stderr);assert r.returncode==expected,(name,r.returncode,r.stdout,r.stderr);proof=json.loads((report/'verification.json').read_text());assert proof['exit_code']==expected and 'Required action:' in (report/'WARNINGS.md').read_text();runs.append(dict(case=name,kind='actual-installer',exit_code=r.returncode,verification_sha256=sha(report/'verification.json')));print(name,'passed',flush=True)
    def cli(name,home,expected):
        destination=out/name;options=out/(name+'-options.json');options.write_text(json.dumps(dict(recipe=str(views),home=str(home),out=str(destination))),encoding='utf-8');command=[args.java,'-jar',str(args.jar.absolute()),'igv-tools','--options-file',str(options)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(out/(name+'.stdout')).write_bytes(r.stdout);(out/(name+'.stderr')).write_bytes(r.stderr);assert r.returncode==expected,(name,r.returncode,r.stderr);session=json.loads((destination/'session.json').read_text());assert session['status']=='skipped-unavailable-dependency' and 'igv-probe_owned_pid' not in session;assert not (destination/'results.json').exists() and 'Required action:' in (destination/'WARNINGS.md').read_text();runs.append(dict(case=name,kind='actual-packaged-prelaunch-skip',exit_code=r.returncode,session_sha256=sha(destination/'session.json')));print(name,'passed',flush=True)
    try:
        install('installation-not-allowed',out/'forbidden-home',args.cache,3);assert not (out/'forbidden-home').exists()
        install('download-not-allowed',out/'no-download-home',out/'empty-cache',3,['--allow-install']);assert not (out/'no-download-home').exists()
        install('healthy-reuse-no-permission-flags',args.home.absolute(),args.cache,0);assert sha(args.home/'.jlinalg-igv.json')==normal_marker
        cache=out/'corrupt-cache';cache.mkdir();bad=cache/'IGV_2.19.8.zip';bad.write_bytes(b'corrupt archive control;never extracted');before=sha(bad);install('corrupt-cache-preserved',out/'corrupt-home',cache,2,['--allow-install','--allow-download']);assert sha(bad)==before and not (out/'corrupt-home').exists()
        unmanaged=out/'unmanaged-home';unmanaged.mkdir();install('unmanaged-home-preserved',unmanaged,args.cache,2,['--allow-install']);cli('unmanaged-runtime-skips',unmanaged,3)
        control=out/'admitted-control-home';install('create-disposable-control-home',control,args.cache,0,['--allow-install']);marker=control/'.jlinalg-igv.json';original_marker=marker.read_bytes();original_marker_sha=sha(marker)
        unlisted=control/'unlisted-negative-control.txt';unlisted.write_text('Unlisted member;analysis must skip before any runtime process.');unlisted_sha=sha(unlisted);cli('unlisted-member-prelaunch-skip',control,3);install('unlisted-installer-rejected',control,args.cache,2);assert sha(unlisted)==unlisted_sha and sha(marker)==original_marker_sha;shutil.copyfile(unlisted,out/'unlisted-control-retained.txt');assert unlisted.resolve().is_relative_to(out.resolve());unlisted.unlink()
        metadata=json.loads(original_marker);key=next(iter(metadata['java_files']));metadata['java_files'][key]='0'*64;marker.write_text(json.dumps(metadata),encoding='utf-8');bad_marker_sha=sha(marker);cli('changed-Java-core-admission-skip',control,3);install('changed-Java-core-admission-rejected',control,args.cache,2);assert sha(marker)==bad_marker_sha;shutil.copyfile(marker,out/'changed-java-marker-retained.json');marker.write_bytes(original_marker);assert sha(marker)==original_marker_sha
        worker=control/'jlinalg-worker/IgvWorker.java';worker.write_bytes(worker.read_bytes()+b'\n// Deliberate integrity control;never executed.\n');changed=sha(worker);cli('changed-helper-prelaunch-skip',control,3);install('changed-helper-installer-rejected',control,args.cache,2);assert sha(worker)==changed and sha(marker)==original_marker_sha
        if args.allow_download_test:install('allowed-official-public-download',out/'public-download-home',out/'public-cache',0,['--allow-install','--allow-download'])
        else:runs.append(dict(case='allowed-official-public-download',status='not-requested;download permission test requires --allow-download-test'))
        assert sha(args.home/'.jlinalg-igv.json')==normal_marker;record.update(status='passed-actual-IGV-dependency-and-integrity-controls',control_entries=len(runs),actual_cases=sum('exit_code' in row for row in runs),not_requested_cases=sum('exit_code' not in row for row in runs),normal_runtime_unchanged=True,control_warning='admitted-control-home deliberately contains a changed helper;preserved as untrusted evidence. Java core files were only read,never edited. Original marker bytes were restored after the marker-only negative control;modified software was never re-sealed.')
    except Exception as failure:record.update(status='failed-retained',error=repr(failure));raise
    finally:record['completed_utc']=dt.datetime.now(dt.timezone.utc).isoformat();(out/'verification.json').write_text(json.dumps(record,indent=2)+'\n',encoding='utf-8');(out/'WARNINGS.md').write_text('# IGV DEPENDENCY CONTROL '+record['status'].upper()+'\n\n'+record.get('error',record.get('control_warning','Incomplete controls.'))+'\n\nRequired action: use the normal admitted runtime for analysis. Never use changed control homes;inspect individual retained reports. If installation is forbidden/unavailable,skip dependent analyses until an administrator supplies an admitted runtime.\n',encoding='utf-8')
    print(json.dumps(dict(status=record['status'],actual_cases=record['actual_cases'],not_requested_cases=record['not_requested_cases'])));return 0
if __name__=='__main__':raise SystemExit(main())
